// Consistent placement: which shard owns each key
const h=s=>{let x=0;for(const ch of s)x=(x*33+ch.charCodeAt(0))>>>0;return x;};
const keys=["sig:u1", "sig:u2", "sig:o9"],N=4;
console.log(keys.map(k=>k+' -> shard '+(h(k)%N)).join('\n'));

